# Names and vault references only -- never values. Resolved at run time by
# pass-cli into the provisioner's process, then discarded.
#
# Format: ENV_VAR=pass://<vault>/<item-title>/<field-label>
# A reference that does not resolve is reported and its step degrades to SKIP,
# so a missing optional secret costs you that one feature, not the run.
#
# Note: TS_OAUTH_SECRET is deliberately absent. Tailscale runs before the vault
# is unlocked, so it cannot come from the vault. Supply it as an environment
# variable for unattended provisioning.

GH_TOKEN=pass://codex/GitHub PAT/API Key
CLAUDE_CODE_OAUTH_TOKEN=pass://codex/Claude Code Token/API Key
ELEVENLABS_API_KEY=pass://codex/ElevenLabs/API Key
OPENROUTER_API_KEY=pass://codex/openrouter/API Key
